// ==== AYARLAR — sadece burayı düzenleyin ====
const AYAR = {
  bitrixWebhook: 'https://xre.bitrix24.com.tr/rest/1/WEBHOOK_KODU/', // Bitrix24 gelen webhook (crm + user izinli). Sonunda / olsun
  bitrixPortal:  'https://xre.bitrix24.com.tr',                      // Kart linki için
  telegramChatId: '-5591560509',
  leadKaynak: 'WEB',                                                  // Bitrix SOURCE_ID
  leadBaslikOnEki: 'Franchise Başvurusu',
  smsMetni: 'XRE franchise başvurunuz alınmıştır. Danışmanımız en kısa sürede sizinle iletişime geçecektir.',
  epostaKonu: 'XRE Franchise Başvurunuz Alındı',
  ercell: {
    url: 'https://ERCELL_XML_API_ADRESI',        // Ercell XML gönderim adresi
    kullanici: 'ERCELL_KULLANICI',
    sifre: 'ERCELL_SIFRE',
    baslik: 'XRE',
    smsTipi: 'UC',
    gonderimTipi: '1:N',
  },
};
// ============================================

const raw = $json.body ?? $json;
const flat = {};
const gizli = new Set();
const put = (k, v) => {
  if (v === undefined || v === null || v === '') return;
  const key = String(k).toLowerCase().replace(/[\s\-\[\]]+/g, '_').replace(/^form_fields_|^fields_|^your_/, '');
  flat[key] = Array.isArray(v) ? v.join(', ') : String(v).trim();
};
// Elementor Pro webhook: fields[id][value] / fields[id][title]
if (raw.fields && typeof raw.fields === 'object') {
  for (const [id, f] of Object.entries(raw.fields)) {
    if (f && typeof f === 'object') {
      put(id, f.value ?? f.raw_value);
      if (f.title) { put(f.title, f.value ?? f.raw_value); gizli.add(String(id).toLowerCase()); }
    }
    else put(id, f);
  }
}
for (const [k, v] of Object.entries(raw)) if (typeof v !== 'object' || Array.isArray(v)) put(k, v);

const pick = (...keys) => { for (const k of keys) if (flat[k]) return flat[k]; return ''; };
let ad = pick('ad', 'isim', 'first_name', 'firstname', 'name_first');
let soyad = pick('soyad', 'soyisim', 'last_name', 'lastname', 'surname');
let adSoyad = pick('ad_soyad', 'adsoyad', 'ad_soyadı', 'adınız_soyadınız', 'full_name', 'fullname', 'name', 'isim_soyisim');
if (!adSoyad) adSoyad = [ad, soyad].filter(Boolean).join(' ');
else if (soyad && !adSoyad.includes(soyad)) { ad = ad || adSoyad; adSoyad = adSoyad + ' ' + soyad; }
if (!ad && adSoyad) { const p = adSoyad.split(/\s+/); soyad = p.length > 1 ? p.pop() : ''; ad = p.join(' '); }

const telHam = pick('telefon', 'tel', 'telefon_numarası', 'telefon_numaranız', 'cep_telefonu', 'gsm', 'phone', 'mobile');
let d = telHam.replace(/\D/g, '');
if (d.startsWith('0090')) d = d.slice(2);
if (d.startsWith('0')) d = '90' + d.slice(1);
if (d.length === 10 && d.startsWith('5')) d = '90' + d;
const telefonSms = d;                          // 905XXXXXXXXX
const telefon = d ? '+' + d : telHam;          // +905XXXXXXXXX

const email = pick('email', 'e_posta', 'eposta', 'e_mail', 'mail', 'e_posta_adresi', 'email_adresi');
const sehir = pick('şehir', 'sehir', 'il', 'city', 'bölge', 'bolge', 'başvuru_yapılan_şehir');
const mesaj = pick('mesaj', 'mesajınız', 'not', 'açıklama', 'aciklama', 'message');

const bilinen = new Set(['ad','isim','first_name','firstname','soyad','soyisim','last_name','lastname','surname','ad_soyad','adsoyad','full_name','fullname','name',
  'telefon','tel','telefon_numarası','cep_telefonu','gsm','phone','mobile','email','e_posta','eposta','e_mail','mail','şehir','sehir','il','city','mesaj','message',
  'form_id','form_name','queried_id','referer_title','_wpcf7','_wpcf7_version','_wpcf7_locale','_wpcf7_unit_tag','_wpcf7_container_post','g_recaptcha_response']);
const ekAlanlar = Object.entries(flat).filter(([k, v]) => !bilinen.has(k) && !gizli.has(k) && v !== adSoyad && v !== telHam && v !== email && !k.startsWith('_') && !k.startsWith('meta')).map(([k, v]) => ({ alan: k, deger: v }));

return [{ json: { ayar: AYAR, ad, soyad, adSoyad, telefon, telefonSms, email, sehir, mesaj, ekAlanlar, tarih: new Date().toLocaleString('tr-TR', { timeZone: 'Europe/Istanbul' }) } }];

const f = $('Form Verisini Hazırla').first().json;
const lead = $('Bitrix: Lead Getir').first().json.result || {};
const userRes = $('Bitrix: Sorumlu Getir').first().json.result;
const u = Array.isArray(userRes) ? userRes[0] : null;
const sorumlu = u ? [u.NAME, u.LAST_NAME].filter(Boolean).join(' ') : 'Atanmadı';
const sorumluTel = u ? (u.PERSONAL_MOBILE || u.WORK_PHONE || '') : '';
const yeni = $('Bitrix: Mükerrer Kontrol').first().json.result?.LEAD?.length ? false : true;
const kartLink = `${f.ayar.bitrixPortal}/crm/lead/details/${lead.ID}/`;
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const satir = [
  '📝 <b>Yeni Franchise Formu Dolduruldu</b>' + (yeni ? '' : ' <i>(mükerrer — mevcut kart)</i>'),
  '',
  `👤 <b>Ad Soyad:</b> ${esc(f.adSoyad)}`,
  `📞 <b>Telefon:</b> ${esc(f.telefon)}`,
  f.email ? `✉️ <b>E-posta:</b> ${esc(f.email)}` : null,
  f.sehir ? `📍 <b>Şehir:</b> ${esc(f.sehir)}` : null,
  ...f.ekAlanlar.map(e => `▫️ <b>${esc(e.alan.replace(/_/g, ' ').replace(/^./, c => c.toLocaleUpperCase('tr')))}:</b> ${esc(e.deger)}`),
  f.mesaj ? `💬 <b>Mesaj:</b> ${esc(f.mesaj)}` : null,
  '',
  `🧑‍💼 <b>Sorumlu:</b> ${esc(sorumlu)}${sorumluTel ? ' (' + esc(sorumluTel) + ')' : ''}`,
  `📊 <b>Durum:</b> ${esc(lead.STATUS_ID || '-')}`,
  `🔗 <a href="${kartLink}">Bitrix Kartı #${lead.ID}</a>`,
  `🕒 ${f.tarih}`,
].filter(x => x !== null).join('\n');

const epostaHtml = `<div style="font-family:Arial,sans-serif;font-size:15px;color:#222;line-height:1.6">
<p>Sayın ${esc(f.adSoyad)},</p>
<p>${esc(f.ayar.smsMetni)}</p>
<p>İlginiz için teşekkür ederiz.</p>
<p><b>XRE Gayrimenkul</b></p></div>`;

return [{ json: { ...f, leadId: lead.ID, kartLink, sorumlu, telegramMetni: satir, epostaHtml } }];
